class DetectTextResult:
    """
    Detection result: structured text items or formatted 2D spatial text string.
"""
    def __init__(self):
        raise RuntimeError("DetectTextResult cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class STRUCTURED:
        """
        Structured list of recognized text lines or words.
"""
        
        def __init__(self, results:typing.List[TextResult]):
            self.results = results
            
            
            pass

    
            
            
    
        def __str__(self):
            return "DetectTextResult.STRUCTURED(results={})".format(self.results)
        def __eq__(self, other):
            if not isinstance(other, DetectTextResult):
                return NotImplemented
            if not other.is_STRUCTURED():
                return False
            if self.results != other.results:
                return False
            return True

    @dataclass
    class SPATIAL:
        """
        Formatted 2D spatial layout text string.
"""
        
        def __init__(self, text:str):
            self.text = text
            
            
            pass

    
            
            
    
        def __str__(self):
            return "DetectTextResult.SPATIAL(text={})".format(self.text)
        def __eq__(self, other):
            if not isinstance(other, DetectTextResult):
                return NotImplemented
            if not other.is_SPATIAL():
                return False
            if self.text != other.text:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_STRUCTURED(self) -> bool:
        return isinstance(self, DetectTextResult.STRUCTURED)
    def is_structured(self) -> bool:
        return isinstance(self, DetectTextResult.STRUCTURED)
    def is_SPATIAL(self) -> bool:
        return isinstance(self, DetectTextResult.SPATIAL)
    def is_spatial(self) -> bool:
        return isinstance(self, DetectTextResult.SPATIAL)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
DetectTextResult.STRUCTURED = type("DetectTextResult.STRUCTURED", (DetectTextResult.STRUCTURED, DetectTextResult,), {})  # type: ignore
DetectTextResult.SPATIAL = type("DetectTextResult.SPATIAL", (DetectTextResult.SPATIAL, DetectTextResult,), {})  # type: ignore




class _UniffiFfiConverterTypeDetectTextResult(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return DetectTextResult.STRUCTURED(
                _UniffiFfiConverterSequenceTypeTextResult.read(buf),
            )
        if variant == 2:
            return DetectTextResult.SPATIAL(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_STRUCTURED():
            _UniffiFfiConverterSequenceTypeTextResult.check_lower(value.results)
            return
        if value.is_SPATIAL():
            _UniffiFfiConverterString.check_lower(value.text)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_STRUCTURED():
            buf.write_i32(1)
            _UniffiFfiConverterSequenceTypeTextResult.write(value.results, buf)
        if value.is_SPATIAL():
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.text, buf)



class _UniffiFfiConverterBytes(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative byte string length")
        return buf.read(size)

    @staticmethod
    def check_lower(value):
        try:
            memoryview(value)
        except TypeError:
            raise TypeError("a bytes-like object is required, not {!r}".format(type(value).__name__))

    @staticmethod
    def write(value, buf):
        buf.write_i32(len(value))
        buf.write(value)






