# RustoBindingError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class RustoBindingError(Exception):
    pass

_UniffiTempRustoBindingError = RustoBindingError

class RustoBindingError:  # type: ignore
    
    class Initialization(_UniffiTempRustoBindingError):
        
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "RustoBindingError.Initialization({})".format(str(self))
    _UniffiTempRustoBindingError.Initialization = Initialization # type: ignore
    class Preprocess(_UniffiTempRustoBindingError):
        
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "RustoBindingError.Preprocess({})".format(str(self))
    _UniffiTempRustoBindingError.Preprocess = Preprocess # type: ignore
    class Inference(_UniffiTempRustoBindingError):
        
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "RustoBindingError.Inference({})".format(str(self))
    _UniffiTempRustoBindingError.Inference = Inference # type: ignore
    class Postprocess(_UniffiTempRustoBindingError):
        
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "RustoBindingError.Postprocess({})".format(str(self))
    _UniffiTempRustoBindingError.Postprocess = Postprocess # type: ignore
    class InvalidInput(_UniffiTempRustoBindingError):
        
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "RustoBindingError.InvalidInput({})".format(str(self))
    _UniffiTempRustoBindingError.InvalidInput = InvalidInput # type: ignore

RustoBindingError = _UniffiTempRustoBindingError # type: ignore
del _UniffiTempRustoBindingError


class _UniffiFfiConverterTypeRustoBindingError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return RustoBindingError.Initialization(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return RustoBindingError.Preprocess(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return RustoBindingError.Inference(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 4:
            return RustoBindingError.Postprocess(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 5:
            return RustoBindingError.InvalidInput(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, RustoBindingError.Initialization):
            _UniffiFfiConverterString.check_lower(value.msg)
            return
        if isinstance(value, RustoBindingError.Preprocess):
            _UniffiFfiConverterString.check_lower(value.msg)
            return
        if isinstance(value, RustoBindingError.Inference):
            _UniffiFfiConverterString.check_lower(value.msg)
            return
        if isinstance(value, RustoBindingError.Postprocess):
            _UniffiFfiConverterString.check_lower(value.msg)
            return
        if isinstance(value, RustoBindingError.InvalidInput):
            _UniffiFfiConverterString.check_lower(value.msg)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, RustoBindingError.Initialization):
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.msg, buf)
        if isinstance(value, RustoBindingError.Preprocess):
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.msg, buf)
        if isinstance(value, RustoBindingError.Inference):
            buf.write_i32(3)
            _UniffiFfiConverterString.write(value.msg, buf)
        if isinstance(value, RustoBindingError.Postprocess):
            buf.write_i32(4)
            _UniffiFfiConverterString.write(value.msg, buf)
        if isinstance(value, RustoBindingError.InvalidInput):
            buf.write_i32(5)
            _UniffiFfiConverterString.write(value.msg, buf)

