class _UniffiFfiConverterTypeRustO:
    @staticmethod
    def lift(value: int) -> RustO:
        return RustO._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: RustO):
        if not isinstance(value, RustO):
            raise TypeError("Expected RustO instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: RustO) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> RustO:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: RustO, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

